<?php

namespace App\Providers;

use App\Models\User;
use Dedoc\Scramble\Scramble;
use Dedoc\Scramble\Support\Generator\OpenApi;
use Dedoc\Scramble\Support\Generator\Operation;
use Dedoc\Scramble\Support\Generator\SecurityScheme;
use Dedoc\Scramble\Support\Generator\ServerVariable;
use Dedoc\Scramble\Support\RouteInfo;
use Illuminate\Support\Facades\Gate;
use Illuminate\Support\ServiceProvider;
use Illuminate\Support\Str;

/**
 * OpenAPI docs of the App API v1 (BRAI-381), generated by Scramble from routes/app-api.php, Form
 * Requests and API Resources. Config: config/scramble.php (only /api/v1, error shape extensions).
 * Here: the Bearer scheme, the `{instance}` server variable and who may open /docs/api.
 * The committed export is docs/api/openapi.json (regenerate: `php artisan scramble:export
 * --path=docs/api/openapi.json`; tests/Feature/AppApi/OpenApiSpecTest.php fails when it is stale).
 */
class AppApiDocsServiceProvider extends ServiceProvider
{
    public function boot(): void
    {
        // /docs/api + /docs/api.json: RestrictedDocsAccess lets `local` through and asks this gate
        // everywhere else. Instance admins only: the spec lists every endpoint, but no content.
        Gate::define('viewApiDocs', fn (User $user): bool => $user->isInstanceAdmin());

        Scramble::configure()
            ->withServerVariables([
                'instance' => ServerVariable::make('www.brainitive.app', description: 'Host of the Brainitive server: Brainitive Cloud or your self-hosted domain.'),
            ])
            // Always the same scheme (also before the first authenticated route exists), so the
            // export doesn't change shape when one is added.
            ->withDocumentTransformers(function (OpenApi $openApi): void {
                $openApi->secure(
                    SecurityScheme::http('bearer', 'bra_... (opaque access token)')
                        ->as('appToken')
                        ->setDescription('Access token from POST /auth/exchange or POST /auth/refresh. 15 minutes; refresh before it expires. Passport tokens (MCP / CLI / extension) are rejected.')
                );
            })
            // Routes without `auth:app` (instance info, code exchange, refresh) are public.
            ->withOperationTransformers(function (Operation $operation, RouteInfo $routeInfo): void {
                $authenticated = collect($routeInfo->route->gatherMiddleware())
                    ->contains(fn ($middleware) => is_string($middleware) && Str::is(['auth', 'auth:*'], $middleware));

                if (! $authenticated) {
                    $operation->security = [];
                }
            });
    }
}
